// Compose the "Connect your accounts" Slack message for one client.
// Steps 1-2 happen on Buffer's and each platform's own pages (client approves there; we never see passwords).
// Step 3 (optional, when buffer_client_id is set): OAuth 2.0 + PKCE link to our Buffer app client.
const c = $('Client config').first().json;
const verifier = $('PKCE verifier').first().json.code_verifier;
const b64 = $json.code_challenge_b64 || '';
const challenge = b64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const state = verifier.slice(0, 32);   // random (hex) one-time value, checked when the code comes back
let oauthUrl = '';
if (c.buffer_client_id) {
  const params = {
    client_id: c.buffer_client_id, redirect_uri: c.buffer_redirect_uri, response_type: 'code',
    scope: 'posts:write posts:read account:read offline_access', state,
    code_challenge: challenge, code_challenge_method: 'S256', prompt: 'consent' };
  oauthUrl = 'https://auth.buffer.com/auth?' + Object.entries(params)
    .map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');
  // keep the verifier for the code exchange (persists for production/webhook runs, not manual test runs)
  const sd = $getWorkflowStaticData('global');
  sd.pkce = sd.pkce || {};
  sd.pkce[state] = { client: c.client_slug, verifier, created: new Date().toISOString() };
}
const steps = [
  `*1. Create your free Buffer account* (2 min, no card): <${c.buffer_signup_url}|buffer.com/signup>. Use your own email; you own this account.`,
  `*2. Connect your accounts*: open <${c.buffer_app_url}|Buffer>, click *+ New → Connect a New Channel*, pick ${c.platforms}. ` +
    `Each one opens the platform's own sign-in/approval page. Approve there; we never see your password. ` +
    `Tip: sign in to the right profile in another tab first. (<${c.buffer_help_url}|Buffer's guide>)`,
];
if (oauthUrl) steps.push(`*3. Give ${c.agency_name} posting access*: <${oauthUrl}|Approve ${c.agency_name} on Buffer>. ` +
    `Buffer shows exactly what we can do (create and read posts). You can revoke it any time in Buffer → Settings → Connected apps. ` +
    `After approving, paste the code from the page you land on here in this channel.`);
else steps.push(`*3. Tell us when done*: reply *done* here. We'll check the channels and set up a one-time secure access key with you.`);
const text = `Hi ${c.client_first_name}! Let's connect your social accounts so ${c.agency_name} can post for you (only posts you approve).`;
const blocks = [
  { type: 'section', text: { type: 'mrkdwn', text: text } },
  ...steps.map(s => ({ type: 'section', text: { type: 'mrkdwn', text: s } })),
  { type: 'context', elements: [{ type: 'mrkdwn', text: `Never share passwords or codes from your phone in this chat. Questions? Just reply here.` }] },
];
return [{ json: { client: c.client_slug, channel: c.slack_channel, text, blocks, oauth_url: oauthUrl || null,
  oauth_state: oauthUrl ? state : null, preview: [text, ...steps].join('\n\n') } }];
